// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Add a reward token to make sure the contract is initialized
        c.addReward(rewardToken);
        // The general rule: after addReward, totalSupply() should be 0 (no staking yet)
        uint256 ts = c.totalSupply();
        assertTrue(ts == 0, "totalSupply should be 0 before any staking");
    }
}

